contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a) public {
        // Read the initial owner before making any state-changing call.
        address initialOwner = c.owner(); if (__ESBMC_reverted()) return;
        // Any successful setOwner call afterwards leaves the guarantee intact;
        // use it only to show the check is reached with real interaction.
        bool ok = c.setOwner(a); if (__ESBMC_reverted()) return;
        address newOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(initialOwner == address(this) && ok && newOwner == a);
    }
    receive() external payable {}
}

